void prepare_upnp_event_notify(struct upnp_event_notify *obj) {
    if (!obj->subscription || !obj->subscription->valid) {
        obj->state = UPNP_EVENT_ERROR;
        return;
    }

    const char *xml_vars = NULL;
    if (obj->subscription->service_type == UPNP_SERVICE_TYPE_MEDIA_SERVER) {
        xml_vars = obj->subscription->media_server_xml;
    } else if (obj->subscription->service_type == UPNP_SERVICE_TYPE_MEDIA_RENDERER) {
        xml_vars = obj->subscription->media_renderer_xml;
    } else {
        obj->state = UPNP_EVENT_ERROR;
        return;
    }

    // Initial buffer size
    size_t buffer_size = 256;
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        obj->state = UPNP_EVENT_ERROR;
        return;
    }

    // Reallocate buffer until message fits
    while (1) {
        int len = snprintf(buffer, buffer_size, "NOTIFY * HTTP/1.1\r\n"
                           "Location: %s\r\n"
                           "NT: upnp:event\r\n"
                           "NTS: ss:leave\r\n"
                           "SID: %s\r\n"
                           "SEQ: %d\r\n"
                           "Content-Type: text/xml; charset=\"utf-8\"\r\n"
                           "Content-Length: %zu\r\n"
                           "\r\n"
                           "%s",
                           obj->subscription->location,
                           obj->subscription->sid,
                           obj->sequence,
                           strlen(xml_vars),
                           xml_vars);

        if (len >= 0 && (size_t)len < buffer_size) {
            break;
        }

        buffer_size *= 2;
        char *new_buffer = realloc(buffer, buffer_size);
        if (!new_buffer) {
            free(buffer);
            obj->state = UPNP_EVENT_ERROR;
            return;
        }
        buffer = new_buffer;
    }

    obj->message = buffer;
    obj->state = UPNP_EVENT_READY;
}

void upnp_event_notify_prepare(struct upnp_event_notify *obj) {
    if (!obj->subscription || obj->subscription->state != SUBSCRIPTION_ACTIVE) {
        obj->state = UPNP_EVENT_ERROR;
        return;
    }

    const char *xml_vars = NULL;
    if (obj->subscription->service_type == SERVICE_TYPE_1)
        xml_vars = get_service_1_xml_vars(obj->subscription);
    else if (obj->subscription->service_type == SERVICE_TYPE_2)
        xml_vars = get_service_2_xml_vars(obj->subscription);
    else {
        obj->state = UPNP_EVENT_ERROR;
        return;
    }

    size_t buffer_size = 256;
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        obj->state = UPNP_EVENT_ERROR;
        return;
    }

    int required_length = snprintf(buffer, buffer_size, "NOTIFY * HTTP/1.1\r\n"
                                            "Content-Type: text/xml\r\n"
                                            "NT: upnp:event\r\n"
                                            "NTS: ss:ev\r\n"
                                            "SID: %s\r\n"
                                            "SEQ: %d\r\n"
                                            "\r\n"
                                            "%s",
                                     obj->subscription->sid,
                                     obj->sequence,
                                     xml_vars);

    while (required_length >= (int)buffer_size) {
        buffer_size *= 2;
        char *new_buffer = realloc(buffer, buffer_size);
        if (!new_buffer) {
            free(buffer);
            obj->state = UPNP_EVENT_ERROR;
            return;
        }
        buffer = new_buffer;
        required_length = snprintf(buffer, buffer_size, "NOTIFY * HTTP/1.1\r\n"
                                           "Content-Type: text/xml\r\n"
                                           "NT: upnp:event\r\n"
                                           "NTS: ss:ev\r\n"
                                           "SID: %s\r\n"
                                           "SEQ: %d\r\n"
                                           "\r\n"
                                           "%s",
                                    obj->subscription->sid,
                                    obj->sequence,
                                    xml_vars);
    }

    obj->message = buffer;
    obj->message_length = required_length;
    obj->state = UPNP_EVENT_READY;
}

